    internal static FusionPlant From(Plant plant) =>
        (plant.mSeedType, plant.mImitaterType) switch
        {
            (SeedType.Puffshroom, SeedType.Magnetshroom) => BuckShroom,
            (SeedType.Puffshroom, SeedType.Cabbagepult) => SproutPult,
            (SeedType.Puffshroom, SeedType.Kernelpult) => BabyCorn,
            (SeedType.Puffshroom, SeedType.Melonpult) => SlicePult,
            (SeedType.Puffshroom, SeedType.Hypnoshroom) => GnomeShroom,
            (SeedType.Puffshroom, SeedType.Umbrella) => UmbrellaCap,
            (SeedType.Puffshroom, SeedType.Iceshroom) => HailShroom,
            (SeedType.Puffshroom, SeedType.Snowpea) => IcicleShroom,
            (SeedType.Puffshroom, SeedType.Starfruit) => TwinkleShroom,
            (SeedType.Puffshroom, SeedType.Potatomine) => NuggetShroom,
            (SeedType.Puffshroom, SeedType.Wallnut) => NutShroom,
            (SeedType.Puffshroom, SeedType.Jalapeno) => BellPepper,
            (SeedType.Puffshroom, SeedType.Doomshroom) => BoomShroom,
            (SeedType.Puffshroom, SeedType.Marigold) => PennyShroom,
